    private static function pluralBE(int $n): PluralCategory
    {
        $mod10 = $n % 10;
        $mod100 = $n % 100;
        if ($mod10 === 1 && $mod100 !== 11) {
            return PluralCategory::One;
        }
        if ($mod10 >= 2 && $mod10 <= 4 && ($mod100 < 12 || $mod100 > 14)) {
            return PluralCategory::Few;
        }

        return PluralCategory::Many;
    }

