    {
        $mod100 = $n % 100;
        if ($mod100 === 1) {
            return PluralCategory::One;
        }
        if ($mod100 === 2) {
            return PluralCategory::Two;
        }
        if ($mod100 === 3 || $mod100 === 4) {
